#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard:generate skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# The agent that authors a wizard never runs it. The human runs it, in a real
# terminal: the library refuses to start without a controlling TTY, so prompts
# cannot be satisfied by piped or pasted input.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — consistent, hardened UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

fatal() { printf '%s✗ %s%s\n' "$RED" "$1" "$RESET" >&2; exit 1; }

# Every prompt reads from the controlling terminal (fd 3 ← /dev/tty), never
# stdin. Fail closed when no TTY exists: a wizard driven by piped input would
# let a multi-line paste blow through its confirmation gates.
if ! { exec 3</dev/tty; } 2>/dev/null; then
  fatal "no interactive terminal (/dev/tty unavailable) — run this wizard from a real terminal, not a pipe or CI"
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret names set this run
WRITTEN_VAR=()    # variable names set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing, gh errors)

# Temp-file hygiene: write_env stages its rewrite in a mktemp file alongside
# ENV_FILE (same filesystem, so the final mv is an atomic rename); the trap
# removes it if the wizard dies mid-write.
_WIZARD_TMP=""
# if-form, not `[[ ]] &&`: a false condition must not leave a nonzero status
# for the EXIT trap under set -e, which would turn a successful run into exit 1.
_cleanup() { if [[ -n "$_WIZARD_TMP" && -f "$_WIZARD_TMP" ]]; then rm -f -- "$_WIZARD_TMP"; fi; }
trap _cleanup EXIT

# _valid_key KEY — keys and secret/variable names must be valid identifiers.
# Anything else (spaces, '=', metacharacters) is an authoring bug: fail fast
# before it reaches the env file or a gh call.
_valid_key() {
  [[ "$1" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || fatal "invalid key name: '$1' (must match ^[A-Za-z_][A-Za-z0-9_]*$)"
}

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — an action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
# https:// only: anything else is refused with a visible warning (this also
# keeps a crafted file:// or UNC path away from the explorer.exe branch on
# Windows, where it could trigger an SMB/NTLM credential leak). The full URL
# is printed BEFORE dispatch so the human sees exactly what is being opened.
# shellcheck disable=SC2310  # warn always succeeds; the || branch is the handled fallback
open_url() {
  local url="$1"
  if [[ "$url" != https://* ]]; then
    warn "refusing to open non-https URL: $url"
    return 0
  fi
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  # explorer.exe exits 1 even on success, so its status must not trip the
  # manual-fallback warning on the supported Git Bash path.
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url" || true
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
# A read failure (terminal closed) is fatal, never silently skipped: a pause
# that falls through at EOF would fail open.
# shellcheck disable=SC2310  # fatal exits the script directly; set -e suppression is moot
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r -u 3 _ || fatal "terminal closed at a pause gate — aborting"
}

# confirm "question" — y/N gate; returns success on yes. Fail-closed: only an
# explicit y/Y answers yes, and a read failure aborts the wizard.
# shellcheck disable=SC2310  # fatal exits the script directly; set -e suppression is moot
confirm() {
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r -u 3 reply || fatal "terminal closed at a confirmation gate — aborting"
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any, with one matched
# pair of surrounding quotes stripped (write_env stores values single-quoted,
# so re-run defaults must offer the value back, not the quoting). For a
# single-quoted line, write_env's escaping ('\'' for an embedded ') is also
# reversed, so Enter-keeps-current never re-escapes an already-escaped value.
_existing() {
  _valid_key "$1"
  [[ -f "$ENV_FILE" ]] || return 1
  local line val esc="'\\''"
  line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1)
  [[ -n "$line" ]] || return 1
  val="${line#*=}"
  if [[ ${#val} -ge 2 ]]; then
    case "$val" in
    \'*\') val="${val:1:${#val}-2}"; val="${val//"$esc"/\'}" ;;
    \"*\") val="${val:1:${#val}-2}" ;;
    *) ;; # unquoted (hand-written line) — offer verbatim
    esac
  fi
  printf '%s' "$val"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), with
# readline editing (-e) so arrow keys work.
# shellcheck disable=SC2310  # fatal exits the script directly; set -e suppression is moot
ask() {
  local key="$1" prompt="$2" current input
  _valid_key "$key"
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r -e -u 3 input || fatal "terminal closed while reading $key — aborting"
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden (no readline: -e
# would echo, and -s must win).
# shellcheck disable=SC2310  # fatal exits the script directly; set -e suppression is moot
ask_secret() {
  local key="$1" prompt="$2" current input
  _valid_key "$key"
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs -u 3 input || fatal "terminal closed while reading secret $key — aborting"
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# _check_env_ignored — warn loudly (once) when ENV_FILE is not gitignored in a
# git repo: a captured secret must never be one `git add .` from a commit.
_ENV_IGNORE_WARNED=0
_check_env_ignored() {
  (( _ENV_IGNORE_WARNED )) && return 0
  command -v git >/dev/null 2>&1 || return 0
  git rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 0
  if ! git check-ignore -q -- "$ENV_FILE" 2>/dev/null; then
    _ENV_IGNORE_WARNED=1
    warn "$ENV_FILE is NOT gitignored — a secret written here can be committed"
    SKIPPED+=("gitignore $ENV_FILE (add it to .gitignore before any commit)")
  fi
}

# write_env KEY VALUE — upsert KEY='VALUE' into ENV_FILE (creates it; replaces
# any existing line). Idempotent. The value is written single-quoted with
# embedded single quotes escaped, so shells and dotenv loaders read it back
# verbatim; the file is chmod 600 after every write.
write_env() {
  local key="$1" value="$2" escaped tmp
  _valid_key "$key"
  _check_env_ignored # pre-flight: warn BEFORE the first value lands on disk
  touch "$ENV_FILE"
  chmod 600 "$ENV_FILE"
  tmp=$(mktemp "${ENV_FILE}.XXXXXX") || fatal "mktemp failed next to $ENV_FILE"
  _WIZARD_TMP="$tmp"
  chmod 600 "$tmp"
  escaped=${value//\'/\'\\\'\'}
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "$escaped" >> "$tmp"
  mv -- "$tmp" "$ENV_FILE"
  _WIZARD_TMP=""
  chmod 600 "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# ── GitHub Actions helpers ────────────────────────────────────────────────
# portability-ok: writing a GitHub Actions repo secret/variable is inherently
# a GitHub-forge capability — these helpers exist only for stages whose
# declared destination is GitHub CI, degrade to SKIPPED when gh is absent,
# and nothing else in this library touches a forge.

# _gh_ready — gh installed and authenticated.
_gh_ready() {
  command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1
}

# _resolve_repo — resolve the target repo ONCE, echo it, and get explicit
# confirmation before the first CI write. Every later gh call passes it via
# --repo so a write can never land in whatever repo the cwd happens to imply.
GH_REPO=""
GH_REPO_DECLINED=0
# shellcheck disable=SC2310  # confirm's no-branch is the handled decline path; fatal exits directly
_resolve_repo() {
  [[ -n "$GH_REPO" ]] && return 0
  (( GH_REPO_DECLINED )) && return 1
  local repo
  if ! repo=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>&1); then
    GH_REPO_DECLINED=1
    warn "couldn't resolve the GitHub repo — CI writes will be skipped"
    SKIPPED+=("resolve GitHub repo (gh repo view failed: ${repo})")
    return 1
  fi
  say "GitHub CI values will be written to: ${BOLD}${repo}${RESET}"
  if ! confirm "Write CI secrets/variables to ${repo}?"; then
    GH_REPO_DECLINED=1
    warn "CI writes to ${repo} declined — set them manually"
    SKIPPED+=("GitHub CI writes (declined for ${repo})")
    return 1
  fi
  GH_REPO="$repo"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh, value piped
# over stdin (never argv). Empty values are refused; gh errors surface into
# the closing summary instead of vanishing into /dev/null.
# shellcheck disable=SC2310  # _gh_ready/_resolve_repo are status-returning gates; every false branch is handled
set_secret() {
  local name="$1" value="$2" err
  _valid_key "$name"
  if [[ -z "$value" ]]; then
    warn "refusing to set GitHub secret $name — empty value"
    SKIPPED+=("GitHub secret $name (empty value — nothing was sent to gh)")
    return 0
  fi
  if ! _gh_ready; then
    warn "skipped GitHub secret $name — gh not ready; set it later"
    SKIPPED+=("GitHub secret $name (gh missing/unauthenticated: gh secret set $name --repo <owner/repo>)")
    return 0
  fi
  if ! _resolve_repo; then
    SKIPPED+=("GitHub secret $name (no confirmed target repo)")
    return 0
  fi
  if err=$(printf '%s' "$value" | gh secret set "$name" --repo "$GH_REPO" 2>&1 >/dev/null); then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s in %s\n' "$GREEN" "$RESET" "$name" "$GH_REPO"
  else
    warn "couldn't set GitHub secret $name — see the closing summary"
    SKIPPED+=("GitHub secret $name (gh error: ${err})")
  fi
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret), value
# piped via --body-file - (stdin), never argv. Same refusals as set_secret.
# shellcheck disable=SC2310  # _gh_ready/_resolve_repo are status-returning gates; every false branch is handled
set_var() {
  local name="$1" value="$2" err
  _valid_key "$name"
  if [[ -z "$value" ]]; then
    warn "refusing to set GitHub variable $name — empty value"
    SKIPPED+=("GitHub variable $name (empty value — nothing was sent to gh)")
    return 0
  fi
  if ! _gh_ready; then
    warn "skipped GitHub variable $name — gh not ready; set it later"
    SKIPPED+=("GitHub variable $name (gh missing/unauthenticated: gh variable set $name --repo <owner/repo>)")
    return 0
  fi
  if ! _resolve_repo; then
    SKIPPED+=("GitHub variable $name (no confirmed target repo)")
    return 0
  fi
  if err=$(printf '%s' "$value" | gh variable set "$name" --repo "$GH_REPO" --body-file - 2>&1 >/dev/null); then
    WRITTEN_VAR+=("$name")
    printf '  %s✓ set%s GitHub variable %s in %s\n' "$GREEN" "$RESET" "$name" "$GH_REPO"
  else
    warn "couldn't set GitHub variable $name — see the closing summary"
    SKIPPED+=("GitHub variable $name (gh error: ${err})")
  fi
}

# finish — clear, then a closing summary of everything configured. Names only
# — never values.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s) in ${GH_REPO}: ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_VAR[@]} ))    && note "set ${#WRITTEN_VAR[@]} GitHub variable(s) in ${GH_REPO}: ${WRITTEN_VAR[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# REPLACE the example below with your real stages, in dependency order, and
# set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=1

banner "Stripe setup"

# ── EXAMPLE STAGE — replace me ────────────────────────────────────────────
# shellcheck disable=SC2154  # ask/ask_secret assign the named variable via printf -v
stage "Stripe — API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
# shellcheck disable=SC2154  # assigned by ask via printf -v
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
# shellcheck disable=SC2154  # assigned by ask_secret via printf -v
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ── END EXAMPLE STAGE ─────────────────────────────────────────────────────

finish
